    MOV P0,0
    MOV VX,P0
    MOV P0,80
    MOV VY,P0
    MOV P0,0
    MOV VL,P0
    ; Display string 'Final score: ' using TEXT
    MOV P0,0x4A00
    MOV P1,15
    TEXT P0,P1
    ; Load STR into P0
    MOV P0,[0x2036]
    ; Display value (number or string)
    MOV P1,P0
    CMP P0,0x4000
    JC display_as_number
    CMP P0,0x8000
    JNC display_as_number
    ; Display as string
    MOV P2,P0
display_str_loop:
    MOV P0,[P2]
    CMP P0,0
    JZ display_value_done
    CMP P0,10
    JZ display_str_newline
    MOV P3,15
    CHAR P0,P3
    INC P2
    JMP display_str_loop
display_str_newline:
    MOV P0,VY
    ADD P0,8
    MOV VY,P0
    MOV P0,0
    MOV VX,P0
    INC P2
    JMP display_str_loop
display_as_number:
    MOV P0,P1
    ; Display as number
    MOV P1,0x6000
    ITOS P1,P0
    MOV P2,P1
display_num_loop:
    MOV P0,[P2]
    CMP P0,0
    JZ display_value_done
    MOV P3,15
    CHAR P0,P3
    INC P2
    JMP display_num_loop
display_value_done:
    ; Load SCORE into P0
    MOV P0,[0x2042]
    ; Display value (number or string)
    MOV P1,P0
    CMP P0,0x4000
    JC display_as_number
    CMP P0,0x8000
    JNC display_as_number
    ; Display as string
    MOV P2,P0
display_str_loop:
    MOV P0,[P2]
    CMP P0,0
    JZ display_value_done
    CMP P0,10
    JZ display_str_newline
    MOV P3,15
    CHAR P0,P3
    INC P2
    JMP display_str_loop
display_str_newline:
    MOV P0,VY
    ADD P0,8
    MOV VY,P0
    MOV P0,0
    MOV VX,P0
    INC P2
    JMP display_str_loop
display_as_number:
    MOV P0,P1
    ; Display as number
    MOV P1,0x6000
    ITOS P1,P0
    MOV P2,P1
display_num_loop:
    MOV P0,[P2]
    CMP P0,0
    JZ display_value_done
    MOV P3,15
    CHAR P0,P3
    INC P2
    JMP display_num_loop
display_value_done:
    ; Pause - wait for key press
pause_loop:
    KEYSTAT P0
    CMP P0,0
    JZ pause_loop
    KEYIN P0

; Program end - infinite loop to keep display visible
